package org.jsoup.nodes;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.Map;
import org.jsoup.SerializationException;
import org.jsoup.helper.Validate;
import org.jsoup.internal.StringUtil;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Attribute_setValue_TriageGen0Test {

    @Test
    public void testSetValue_WithParentAndExistingKey() {
        // Setup parent and attributes
        Attributes parent = new Attributes();
        parent.add("key1", "oldValue");

        Attribute attr = new Attribute("key1", "initialValue", parent);

        // Execute
        String oldValue = attr.setValue("newValue");

        // Verify return value (old value)
        assertEquals("oldValue", oldValue);
        // Verify attribute internal state
        assertEquals("newValue", attr.getValue());
        // Verify parent state update
        assertEquals("newValue", parent.get("key1"));
    }

    @Test
    public void testSetValue_WithParentButKeyNotFound() {
        // Setup parent but key is not in parent
        Attributes parent = new Attributes();
        Attribute attr = new Attribute("missingKey", "initialValue", parent);

        // Execute
        String oldValue = attr.setValue("newValue");

        // Verify return value (old value)
        assertEquals("initialValue", oldValue);
        // Verify attribute internal state
        assertEquals("newValue", attr.getValue());
        // Verify parent remains unchanged regarding this key
        assertNull(parent.get("missingKey"));
    }

    @Test
    public void testSetValue_WithNoParent() {
        // Setup attribute without parent
        Attribute attr = new Attribute("key", "initialValue");

        // Execute
        String oldValue = attr.setValue("newValue");

        // Verify return value
        assertEquals("initialValue", oldValue);
        // Verify attribute internal state
        assertEquals("newValue", attr.getValue());
    }

    @Test
    public void testSetValue_NullValue() {
        // Test behavior with null input
        Attributes parent = new Attributes();
        parent.add("key", "old");
        Attribute attr = new Attribute("key", "initial", parent);

        String oldValue = attr.setValue(null);

        assertEquals("old", oldValue);
        assertNull(attr.getValue());
        assertNull(parent.get("key"));
    }

    @Test
    public void testSetValue_EmptyString() {
        Attributes parent = new Attributes();
        parent.add("key", "old");
        Attribute attr = new Attribute("key", "initial", parent);

        String oldValue = attr.setValue("");

        assertEquals("old", oldValue);
        assertEquals("", attr.getValue());
        assertEquals("", parent.get("key"));
    }
}
